const source = "Frontend BR";
const shape = "array";
const now = new Date().toISOString();
const items=$input.all();
const raw=items.map(i=>i.json);
const response=raw.length===1?raw[0]:raw;
let statusCode=null, headers={}, body=response;
if(response && typeof response==='object' && !Array.isArray(response)) {
  if (response.statusCode!==undefined) {
    statusCode=Number(response.statusCode);
    headers=response.headers||{};
    body=response.body;
  }
}
function getHeader(key){return Object.keys(headers).find(k=>k.toLowerCase()===key.toLowerCase());}
const retryKey=getHeader('retry-after');
const retryAfter=retryKey?String(headers[retryKey]):null;
let error='';
if (!items.length) error='Nenhum item retornado pelo nó HTTP';
else if(raw.some(x=>x && (x.error||x.message&&x.name==='NodeApiError'))) {
  error=String((raw.find(x=>x&&(x.error||x.name==='NodeApiError'))||{}).message||'Falha de rede ou requisição');
}
if(statusCode!==null && (statusCode<200 || statusCode>=300)) {
  error=`HTTP ${statusCode}: ${String(body?.message||body?.error||error||'Falha HTTP').slice(0,250)}`;
}
let jobs=[];
if(!error){
  if (shape==='array') {
    if (Array.isArray(body)) jobs=body.filter(x=>x && typeof x==='object' && !x.pull_request);
    else error='Resposta inesperada: esperado array de issues';
  }else if(body && typeof body==='object' && !Array.isArray(body) && Array.isArray(body[shape])) {
    jobs=body[shape];
  }else {
    error=`Resposta inesperada: campo ${shape} ausente ou inválido`;
  }
}
if(!error && jobs.some(x=>!x||typeof x!=='object'||Array.isArray(x))) {
  error='Resposta contém vagas em formato inválido';jobs=[];
}
// 200 com lista vazia é sucesso. 403/429 indica limites; registrar Retry-After, sem retry infinito.
return [{json:{source,ok:!error,statusCode,checkedAt:now,retryAfter,
  jobs:error?[]:jobs,error:error||null,count:error?null:jobs.length}}];

