// MonitoramentoVagas — consolidação resiliente (n8n Code, Run Once for All Items).
// Mantém o contrato do frontend: atualizadoEm, total e vagas com campos legados.
const now = new Date().toISOString();
const MAX = 400;
const sources = [
  { name: 'Frontend BR', node: 'Validar Frontend BR' },
  { name: 'Backend BR', node: 'Validar Backend BR' },
  { name: 'Himalayas', node: 'Validar Himalayas' },
  { name: 'Adzuna', node: 'Validar Adzuna' },
  { name: 'Jooble', node: 'Validar Jooble' },
];
const checks = sources.map(s => ({ name:s.name, ...$(s.node).first().json }));
const file = $input.first().json;
if (!file || !file.sha || typeof file.content !== 'string') {
  throw new Error('Leitura do histórico falhou. Publicação bloqueada para preservar vagas existentes.');
}
let previous;
try { previous = JSON.parse(Buffer.from(file.content.replace(/\s/g,''),'base64').toString('utf8')); }
catch (e) { throw new Error('Histórico do GitHub está inválido: '+e.message); }
if (!previous || !Array.isArray(previous.vagas)) throw new Error('Histórico não contém o array vagas: publicação bloqueada.');
const old = previous.vagas;
const ok = checks.filter(s => s.ok);
const info = checks.map(s => ({ fonte:s.name, sucesso:Boolean(s.ok), statusCode:s.statusCode ?? null,
    consultadoEm:s.checkedAt ?? now, quantidade:Array.isArray(s.jobs)?s.jobs.length:0,
    erro:s.ok?null:(s.error||'Falha desconhecida'), retryAfter:s.retryAfter??null }));
if (!ok.length) {
  return [{json:{changed:false,relevantChange:false,total:old.length,novos:0,sha:file.sha,
    content:null,preserveHistory:true,reason:'Todas as fontes falharam; histórico preservado',diagnosticos:info}}];
}
const clean = v => String(v??'').replace(/<[^>]*>/g,' ').replace(/\s+/g,' ').trim();
function normalizeUrl(value) {
  let s=String(value||'').trim(); if(!/^https?:\/\//i.test(s)) return '';
  try { const u=new URL(s); u.hash='';
    for (const k of [...u.searchParams.keys()])
      if (/^(utm_.*|gclid|fbclid|mc_cid|mc_eid|ref_src)$/i.test(k)) u.searchParams.delete(k);
    return u.toString().replace(/\?$/,'');
  } catch {return ''}
}
const norm = s => clean(s).normalize('NFKD').replace(/[\u0300-\u036f]/g,'').toLowerCase().replace(/[^a-z0-9]+/g,' ').trim();
function validDate(x) {
  if(x===undefined||x===null||x==='') return '';
  let d;
  if(typeof x==='number' || /^\d{10,13}$/.test(String(x))) {
    const n=Number(x); d=new Date(n<1e11?n*1000:n);
  } else d=new Date(x);
  return Number.isNaN(d.getTime())?'':d.toISOString();
}
function row(raw, source) {
  if (!raw || typeof raw!=='object' || Array.isArray(raw)) return null;
  // As 5 APIs devolvem nomes diferentes para os mesmos campos.
  const title=clean(raw.title||raw.cargo||raw.job_title||'');
  const comp=clean(raw.company?.display_name||raw.company?.name||raw.companyName||raw.company||raw.empresa||raw.employer?.name||'Ver anúncio');
  const url=normalizeUrl(raw.html_url||raw.applicationLink||raw.redirect_url||raw.link||raw.url||'');
  const id0=raw.id??raw.guid??raw.uuid??url;
  if(!title || !id0 || !url) return null;
  const desc=clean(raw.body||raw.description||raw.descricao||raw.snippet||'').slice(0,1500);
  const loc=clean(raw.location?.display_name||raw.location?.name||raw.location||raw.local||raw.candidate_required_location||'Brasil / ver anúncio');
  const levelText=`${title} ${desc}`;
  const nivel=/\b(est[aá]gio|estagi[aá]ri[oa]|intern(ship)?|aprendiz)\b/i.test(levelText)?'Estágio':
    /\btrainee\b/i.test(levelText)?'Trainee':/\b(junior|júnior|jr\.?|entry[ -]?level)\b/i.test(levelText)?'Júnior':'Não informada';
  const modalidade=/\b(remot[oa]|home[ -]?office|remote)\b/i.test(`${title} ${desc}`)?'Remoto':
    /\b(h[ií]brid[oa]|hybrid)\b/i.test(`${title} ${desc}`)?'Híbrido':'Não informada';
  const entryId=String(id0).slice(0,160);
  return {id:`${source.toLowerCase().replace(/\W+/g,'-')}-${entryId}`.slice(0,200),cargo:title,empresa:comp,nivel,modalidade,
    local:loc,descricao:desc.slice(0,500),publicadoEm:validDate(raw.created_at||raw.created||raw.publishedAt||raw.pubDate||raw.date||raw.publication_date),
    fonte:source,link:url,capturadoEm:now,primeiraIdentificacao:now,ultimaIdentificacao:now,statusIdentificacao:'nova',
    urlNormalizada:url,empresaNormalizada:norm(comp),cargoNormalizado:norm(title),fontesAlternativas:[source]};
}
function extractJobs(s){
  return (Array.isArray(s.jobs)?s.jobs:[]).map(v=>row(v,s.name)).filter(Boolean);
}
const incoming=ok.flatMap(extractJobs);
const byId=new Map(); const byUrl=new Map(); const merged=new Map();
for (const v of old){
  if(!v || !v.id) continue;
  const copy={...v};
  merged.set(v.id,copy);
  byId.set(v.id,copy);
  const url=normalizeUrl(v.urlNormalizada||v.link);
  if(url) byUrl.set(url,copy);
}
let additions=0;
for (const v of incoming){
  const prev=byId.get(v.id)||(v.urlNormalizada?byUrl.get(v.urlNormalizada):null);
  if(prev){
    // IDs e metadados de primeira captura não podem ser sobrescritos.
    const result={...prev,...v,
      id:prev.id,
      primeiraIdentificacao:prev.primeiraIdentificacao||prev.capturadoEm||now,
      capturadoEm:prev.capturadoEm||prev.primeiraIdentificacao||now,
      publicadoEm:prev.publicadoEm||v.publicadoEm||'',
      statusIdentificacao:prev.statusIdentificacao==='nova'?'existente':(prev.statusIdentificacao||'existente'),
      // Não atualizar a cada consulta: evita commit apenas por horário.
      ultimaIdentificacao:prev.ultimaIdentificacao||prev.capturadoEm||now,
      fontesAlternativas:[...new Set([...(prev.fontesAlternativas||[]),prev.fonte,v.fonte].filter(Boolean))]
    };
    merged.set(prev.id,result); byId.set(v.id,result);
    if(v.urlNormalizada) byUrl.set(v.urlNormalizada,result);
  }else{
    additions++;
    merged.set(v.id,v);byId.set(v.id,v);if(v.urlNormalizada)byUrl.set(v.urlNormalizada,v);
  }
}
const sortKey=v=>validDate(v.primeiraIdentificacao||v.capturadoEm||v.publicadoEm)||'';
const candidate=[...merged.values()].sort((a,b)=>sortKey(b).localeCompare(sortKey(a))||String(a.id).localeCompare(String(b.id))).slice(0,MAX);
// Comparação ignorando ordem original, dados voláteis e mudanças meramente cosméticas.
function comparable(v){
  return {id:v.id,cargo:v.cargo,empresa:v.empresa,nivel:v.nivel,modalidade:v.modalidade,local:v.local,
    descricao:v.descricao,publicadoEm:v.publicadoEm,fonte:v.fonte,link:v.link,
    primeiraIdentificacao:v.primeiraIdentificacao||v.capturadoEm||'',
    fontesAlternativas:[...(v.fontesAlternativas||[])].sort()};
}
const fingerprint=a=>JSON.stringify(a.map(comparable).sort((x,y)=>String(x.id).localeCompare(String(y.id))));
const changed=fingerprint(old)!==fingerprint(candidate);
const lastGood={...(previous.ultimaConsultaBemSucedida||{})};
for(const s of ok)lastGood[s.name]=s.checkedAt||now;
const payload={...previous, atualizadoEm:changed?now:(previous.atualizadoEm||now),total:candidate.length,vagas:candidate,
  ultimaSincronizacao:now,
  ultimaSincronizacaoCompleta:ok.length===sources.length?now:(previous.ultimaSincronizacaoCompleta||null),
  ultimaSincronizacaoParcial:ok.length<sources.length?now:null,
  limiteHistorico:MAX,historicoPreservado:true,novasNaExecucao:additions,
  ultimaConsultaBemSucedida:lastGood,
  // Este diagnóstico será persistido somente quando houver publicação por vagas alteradas.
  diagnosticosFontes:info};
return [{json:{changed,relevantChange:changed,total:candidate.length,novos:additions,sha:file.sha,
  content:changed?Buffer.from(JSON.stringify(payload,null,2)+'\n').toString('base64'):null,
  preserveHistory:true,reason:changed?'Vagas atualizadas':'Nenhuma alteração relevante',diagnosticos:info}}];

const input=$input.first().json;
const status=Number(input.statusCode||0);
const body=input.body||{};
const message=String(body.message||'');
const success=status===200||status===201;
const conflict=status===409||status===422;
if(!success) throw new Error(`Falha na publicação GitHub HTTP ${status||'desconhecido'}: ${message||'verifique credenciais, SHA e permissões'}${conflict?' (SHA possivelmente desatualizado; execute novamente o workflow para reler o arquivo)':''}`);
return [{json:{statusCode:status,conflict:false,message:'Publicado com sucesso',shouldRetry:false,publicationAttempted:true}}];
